CustomAlgorithm.AlgorithmText:
if (Octet1 !== null && Octet2 !== null && Octet3 !== null && Octet4 !== null) {
    IPAddress = Octet1 + "." + Octet2 + "." + Octet3 + "." + Octet4;
}
else {
    IPAddress = "0.0.0.0";
}
widget.setValue(IPAddress);

switch (type.value) {
    case "init":
    case "info":
         EventLog.info(type.value + ': [' + subsystem.value + '] ' + message.value);
         break;
    case "cmd":  
    case "cmd_ack":  
    case "cmd_resp":  
         EventLog.watch(type.value + ': [' + subsystem.value + '] ' + message.value);    
         break;
    case "cmd_fail":  
    case "warning":
         EventLog.warning(type.value + ': [' + subsystem.value + '] ' + message.value);    
         break;
    default:
         EventLog.severe(type.value + ': [' + subsystem.value + '] ' + message.value);    
         break;
}

